class WordDictionary {
    private static class TrieNode {
        TrieNode[] children = new TrieNode[26];
        boolean isWord;
    }
    private final TrieNode root = new TrieNode();
    public WordDictionary() {}
    public void addWord(String word) {
        TrieNode node = root;
        for (int index = 0; index < word.length(); index++) {
            int letter = word.charAt(index) - 'a';
            if (node.children[letter] == null) node.children[letter] = new TrieNode();
            node = node.children[letter];
        }
        node.isWord = true;
    }
    public boolean search(String pattern) { return matches(pattern, 0, root); }
    private boolean matches(String pattern, int index, TrieNode node) {
        if (index == pattern.length()) return node.isWord;
        char value = pattern.charAt(index);
        if (value != '.') {
            TrieNode next = node.children[value - 'a'];
            return next != null && matches(pattern, index + 1, next);
        }
        for (TrieNode next : node.children) if (next != null && matches(pattern, index + 1, next)) return true;
        return false;
    }
}
